import { cells } from "./format";
import type { BarItem, BarRow, Card, Item, Span, TextItem } from "./interfaces/card.interface";
import { THEME } from "./theme";

/** Level from which the cards tighten their padding and gaps. */
const TIGHT_FROM = 2;

/** A bold span, white unless told: the primary text. */
export const strong = (text: string, color: string = THEME.text): Span => ({
	text,
	color,
	bold: true,
});

/** A regular span in the muted color. */
export const muted = (text: string): Span => ({ text, color: THEME.muted });

/** A text item. */
export const text = (...spans: Span[]): TextItem => ({ kind: "text", spans });

/** A bar item of `width` cells with one or two stripes. */
export const bar = (width: number, label: string, ...rows: BarRow[]): BarItem => ({
	kind: "bar",
	width,
	rows,
	label,
});

const widthOf = (item: Item): number =>
	item.kind === "bar" ? item.width : item.spans.reduce((n, s) => n + cells(s.text), 0);

/**
 * Wraps items in a card: padding and gaps tighten as the abbreviation level rises.
 *
 * @param id - The card's name
 * @param importance - Higher stays longer when the room runs out
 * @param level - 0 (everything) up to the most abbreviated
 * @param items - What the card holds, in order
 * @returns The card, or `null` when it holds nothing
 */
export function makeCard(
	id: string,
	importance: number,
	level: number,
	items: Item[],
): Card | null {
	if (items.length === 0) return null;
	const tight = level >= TIGHT_FROM;
	const pad = tight ? 1 : 2;
	const gap = tight ? 1 : 2;
	const inner = items.reduce((n, i) => n + widthOf(i), 0) + gap * (items.length - 1);
	return { id, importance, pad, gap, items, width: inner + 2 * pad };
}

files.interfaces/card.interface.ts:
import type { Span } from "../types";

export type {
	CacheFigures,
	EngineFacts,
	EngineLimits,
	ExtraCredits,
	Facts,
	Flags,
	RateWindow,
	Span,
} from "../types";

/** One stripe of a bar: how full it is and the color of its fill. */
export interface BarRow {
	ratio: number;
	fill: string;
}

/** Text in one or more styles. */
export interface TextItem {
	kind: "text";
	spans: Span[];
}

/** A slim bar of `width` cells; two rows are stacked in the height of one. */
export interface BarItem {
	kind: "bar";
	width: number;
	rows: BarRow[];
	/** What the bar says, for a reader that cannot see it. */
	label: string;
	/** Text centered over a thick pill bar (desktop): the bar then has one row and no side text. */
	overlay?: string;
}

/** Anything a card holds. */
export type Item = TextItem | BarItem;

/** One run of identical bar cells: its glyphs, foreground and, for stacked bars, background. */
export interface BarRun {
	text: string;
	color: string;
	bg?: string;
}

/** One chip on the bar: its items, drawn side by side, are never split across rows. */
export interface Card {
	id: string;
	/** Higher stays longer when the room runs out. */
	importance: number;
	/** Cells of padding on each side. */
	pad: number;
	/** Cells between two items. */
	gap: number;
	items: Item[];
	/** Cells the card takes, padding included. */
	width: number;
}

/** One drawn row of cards. */
export type Row = Card[];

/**
 * Hook Input Interface - Claude Code JSON structure
 *
 * @see https://code.claude.com/docs/en/statusline
 */

export interface TokenUsage {
	input_tokens: number;
	cache_creation_input_tokens?: number;
	cache_read_input_tokens?: number;
}

export interface HookInput {
	session_id: string;
	transcript_path: string;
	cwd: string;
	model: {
		id: string;
		display_name: string;
	};
	workspace: {
		current_dir: string;
		project_dir: string;
	};
	version: string;
	output_style: {
		name: string;
	};
	cost?: {
		total_cost_usd: number;
		total_duration_ms: number;
		total_api_duration_ms: number;
		total_lines_added: number;
		total_lines_removed: number;
	};
	context_window?: {
		total_input_tokens: number;
		total_output_tokens: number;
		context_window_size: number;
		used_percentage?: number | null;
		remaining_percentage?: number;
		current_usage: TokenUsage;
	};
	exceeds_200k_tokens?: boolean;
	agent?: {
		name: string;
	};
	/** Unique subagent identifier (present in subagent context) */
	agent_id?: string;
	/** Agent type name e.g. "Explore", "security-reviewer" (present in subagent/--agent context) */
	agent_type?: string;
	/** Worktree info (present only during --worktree sessions) */
	worktree?: {
		/** Worktree name */
		name: string;
		/** Worktree absolute path */
		path: string;
		/** Worktree branch name */
		branch?: string;
		/** Original working directory before worktree switch */
		original_cwd: string;
		/** Original branch before worktree switch */
		original_branch?: string;
	};
	/** Active reasoning effort (absent if the model does not support the effort param) */
	effort?: {
		/** Effort level, e.g. "high" (open string, no fixed enum documented) */
		level: string;
	};
	/** Extended thinking state */
	thinking?: {
		enabled: boolean;
	};
	/** Fast mode state */
	fast_mode?: boolean;
}

files.labels.ts:
const MS = { minute: 60_000, hour: 3_600_000, day: 86_400_000 } as const;

/**
 * The model as the card names it: family in capitals, version with dots.
 * `claude-opus-5-5` and `Opus 5.5[1m]` both give `OPUS 5.5`.
 *
 * @param raw - `$.session.model()`
 * @returns The label; empty when the model is unknown
 */
export function modelLabel(raw: string): string {
	const parts = raw
		.replace(/\[[^\]]*\]/g, "")
		.replace(/-\d{8}$/, "")
		.replace(/^claude[-\s]?/i, "")
		.split(/[-\s.]+/)
		.filter(Boolean);
	const words = parts.filter((p) => !/^\d+$/.test(p)).map((p) => p.toUpperCase());
	const version = parts.filter((p) => /^\d+$/.test(p)).join(".");
	return [...words, version].filter(Boolean).join(" ");
}

/** `medium` to `Medium`. */
export const capitalize = (s: string): string => s.charAt(0).toUpperCase() + s.slice(1);

/**
 * The model as the old statusline names it: `claude-mythos-5-1` gives `Mythos 5.1`.
 *
 * @param raw - `$.session.model()`
 * @returns The display name; empty when the model is unknown
 */
export const modelName = (raw: string): string =>
	modelLabel(raw)
		.split(" ")
		.map((w) => (/^\d/.test(w) ? w : capitalize(w.toLowerCase())))
		.join(" ");

/**
 * Tokens as `0.0K`, `590.0K`, `1M`, `1.5M`.
 *
 * @param n - Token count
 * @param decimals - One decimal on thousands, else rounded
 * @returns The figure with its unit
 */
export function formatTokens(n: number, decimals: boolean): string {
	if (n >= 1_000_000) {
		const m = n / 1_000_000;
		return Number.isInteger(m) ? `${m}M` : `${m.toFixed(1)}M`;
	}
	const k = n / 1000;
	return decimals ? `${k.toFixed(1)}K` : `${Math.round(k)}K`;
}

/**
 * Time left as `2h33m`, `6d 16h`, `45m`.
 *
 * @param ms - Milliseconds until the reset
 * @returns The duration, at most two units
 */
export function formatLeft(ms: number): string {
	if (ms <= 0) return "0m";
	const d = Math.floor(ms / MS.day);
	const h = Math.floor((ms % MS.day) / MS.hour);
	const m = Math.floor((ms % MS.hour) / MS.minute);
	if (d > 0) return `${d}d ${h}h`;
	if (h > 0) return `${h}h${m.toString().padStart(2, "0")}m`;
	return `${m}m`;
}

/** The word before the prompt-cache hit ratio, on every surface: `Hit 99%` (owner request, 1.0.13). */
export const CACHE_LABEL = "Hit";

/** An amount as the card writes it: `58.00 $`. */
export const money = (usd: number, decimals: number): string => `${usd.toFixed(decimals)} $`;

